<script lang="ts">
 import {onMount} from 'svelte';
 import type {LibraryEntry,LocalProgress,Progress,ProgressStorage,ReadingGateway} from '../application/progress';
 import {importGuest as transferGuest} from '../application/guest-import';
 let {readingGateway,progressStorage}:{readingGateway:ReadingGateway;progressStorage:ProgressStorage}=$props();
 let entries=$state<LibraryEntry[]>([]),guests=$state<LocalProgress[]>([]),account=$state<string|null>(null),busy=$state(true),more=$state(false),message=$state(''),filter=$state('all'),conflict=$state<{guest:LocalProgress;cloud:Progress}|null>(null),valid=true;
 const statusNames:Record<string,string>={reading:'Оқып жүрмін',planned:'Жоспарда',completed:'Оқып болдым',paused:'Үзілісте',dropped:'Тоқтаттым'};
 onMount(()=>{const stop=progressStorage.watchAccountChange(()=>{valid=false;entries=[];account=null;message='Есептікжазба өзгерді. Бетті жаңартыңыз.';});void load();return ()=>{valid=false;stop();};});
 async function load(after=''){busy=true;try{const current=account||await readingGateway.account();const guestRows=await progressStorage.list('guest');if(!valid)return;guests=guestRows;account=current;if(current){const result=await readingGateway.list(current,after);if(!valid)return;entries=after?[...entries,...result.items]:result.items;more=result.hasMore;}}catch(failure){message=failure instanceof Error?failure.message:'Кітапхана жүктелмеді';}finally{busy=false;}}
 async function update(item:LibraryEntry){if(!account)return;try{await readingGateway.save(account,item);message='Сақталды';}catch(failure){message=failure instanceof Error?failure.message:'Сақтау мүмкін болмады';}}
 async function remove(item:LibraryEntry){if(!account)return;try{await readingGateway.remove(account,item.titleId);entries=entries.filter(entry=>entry.titleId!==item.titleId);}catch{message='Өшіру мүмкін болмады';}}
 async function importGuest(guest:LocalProgress,baseVersion?:number){if(!account)return;busy=true;try{const cloud=await transferGuest(readingGateway,progressStorage,account,guest,baseVersion);if(cloud){conflict={guest,cloud};message='Бұлттағы орын бар. Қай нұсқаны сақтау керегін таңдаңыз.';return;}conflict=null;message='Қонақтағы орын импортталды';await load();}catch{message='Импорттау мүмкін болмады. Тарау жаңарған немесе желі үзілген болуы мүмкін.';}finally{busy=false;}}
</script>
<svelte:head><title>Кітапхана — Qmanga</title><meta name="robots" content="noindex"/></svelte:head>
<div class="library-heading"><h1>Кітапхана</h1><a class="button subtle" href="/saved">Сақталған тараулар</a></div>
{#if message}<p role="status" class="form-message">{message}</p>{/if}
{#if account}<label class="filter">Тізім<select bind:value={filter}><option value="all">Барлығы</option><option value="favorites">Таңдаулы</option>{#each Object.entries(statusNames) as [value,label]}<option {value}>{label}</option>{/each}</select></label>
 {#each entries.filter(item=>filter==='all'||filter==='favorites'&&item.favorite||item.status===filter) as item}<article><a class="title" href={`/titles/${item.slug}`}>{item.name}</a><p class="muted">{item.unseen} оқылмаған тарау</p><div class="entry-controls"><select aria-label={`${item.name}: мәртебесі`} bind:value={item.status} onchange={()=>update(item)}>{#each Object.entries(statusNames) as [value,label]}<option {value}>{label}</option>{/each}</select><label><input type="checkbox" bind:checked={item.favorite} onchange={()=>update(item)}/>Таңдаулы</label>{#if item.progress.releaseId}<a class="button primary" href={`/read/${item.progress.releaseId}`}>Жалғастыру</a>{/if}<button class="button subtle" onclick={()=>remove(item)}>Тізімнен алу</button></div></article>{:else}{#if !busy}<p class="empty-state">Бұл тізімде тайтл жоқ. Тайтл бетінде кітапханаға қосыңыз.</p>{/if}{/each}
 {#if more}<button class="button" disabled={busy} onclick={()=>load(entries[entries.length-1].titleId)}>Тағы жүктеу</button>{/if}
{:else if !busy}<p class="muted">Қонақтағы оқу орны осы құрылғыда сақталады. Құрылғылар арасында сақтау үшін <a class="auth-link" href="/login">кіріңіз</a>.</p>{/if}
{#if busy}<p role="status">Жүктелуде…</p>{/if}
{#if guests.length}<section><h2>Қонақ ретінде оқылған</h2><p class="muted">Есептікжазбаға автоматты қосылмайды. Импортты өзіңіз таңдаңыз.</p>{#each guests as guest}<article><a class="title" href={`/titles/${guest.slug}`}>{guest.name}</a><div class="entry-controls"><a class="button subtle" href={`/read/${guest.progress.releaseId}`}>Оқу</a>{#if account}<button class="button subtle" disabled={busy} onclick={()=>importGuest(guest)}>Осы орынды импорттау</button>{/if}</div></article>{/each}</section>{/if}
{#if conflict}<section class="conflict"><h2>Оқу орны әртүрлі</h2><p>{conflict.guest.name} үшін бұлтта да орын бар. Импорт бұлттағы орынды ауыстырады.</p><div class="entry-controls"><button class="button primary" onclick={()=>importGuest(conflict!.guest,conflict!.cloud.version)} disabled={busy}>Қонақтағы орынды сақтау</button><button class="button subtle" onclick={()=>conflict=null}>Бұлттағыны қалдыру</button></div></section>{/if}
<style>.library-heading{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px}h1{font-size:26px}.filter{display:grid;gap:8px;max-width:320px;margin:24px 0;font-size:14px}article{border-bottom:1px solid var(--line);padding:20px 0}.title{font-size:18px;font-weight:600;display:inline-flex;align-items:center;min-height:44px}.entry-controls{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-top:12px}.entry-controls select{max-width:240px}.entry-controls label{display:flex;align-items:center;gap:8px;min-height:44px}.entry-controls input{width:20px;height:20px;min-height:20px}section{margin-top:36px}h2{font-size:21px}.conflict{border:1px solid var(--line);padding:20px}</style>
